\set ON_ERROR_STOP on
begin;
create function private.quote_assert(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAILED: %',label;end if;raise notice 'PASS: %',label;end$$;
create function private.quote_denied(command text,states text[],label text) returns void language plpgsql as $$begin begin execute command;exception when others then if sqlstate=any(states) then raise notice 'PASS: %',label;return;end if;raise exception 'FAILED: % (%: %)',label,sqlstate,sqlerrm;end;raise exception 'FAILED: % allowed',label;end$$;
insert into auth.users(id,email) values('b0000000-0000-4000-8000-000000000001','quote-other@example.test');
select set_config('request.jwt.claim.sub','b0000000-0000-4000-8000-000000000001',true);
select public.create_organization('{"name":"Quote Other","slug":"quote-other","currency":"USD","country":"US","timezone":"UTC"}') as other_org \gset
insert into public.customers(id,organization_id,display_name) values('b0000000-0000-4000-8000-000000000002',:'other_org','Private customer');
insert into public.projects(id,organization_id,customer_id,name,code) values('b0000000-0000-4000-8000-000000000003',:'other_org','b0000000-0000-4000-8000-000000000002','Private project','private');
insert into public.project_areas(id,organization_id,project_id,name) values('b0000000-0000-4000-8000-000000000004',:'other_org','b0000000-0000-4000-8000-000000000003','Private area');
insert into public.customer_contacts(organization_id,customer_id,name) values(:'other_org','b0000000-0000-4000-8000-000000000002','Private contact');
insert into public.organization_quotation_settings(organization_id,branding) values(:'other_org','{"name":"Private studio"}');
insert into public.quotations(id,organization_id,customer_id,project_id,quotation_number) values('b0000000-0000-4000-8000-000000000005',:'other_org','b0000000-0000-4000-8000-000000000002','b0000000-0000-4000-8000-000000000003','Q-PRIVATE');
insert into public.quotation_revisions(id,organization_id,quotation_id,project_id,revision_number,currency,valid_until,document_snapshot) values('b0000000-0000-4000-8000-000000000006',:'other_org','b0000000-0000-4000-8000-000000000005','b0000000-0000-4000-8000-000000000003',1,'USD',current_date,'{}');
insert into public.quotation_items(id,organization_id,revision_id,project_id,snapshot) values('b0000000-0000-4000-8000-000000000007',:'other_org','b0000000-0000-4000-8000-000000000006','b0000000-0000-4000-8000-000000000003','{"snapshot_version":1}');
insert into public.quotation_item_costs(organization_id,item_id,cost_snapshot) values(:'other_org','b0000000-0000-4000-8000-000000000007','{"estimatedCost":"999"}');
select set_config('test.quote_other',:'other_org',true);
set local role authenticated;
select set_config('request.jwt.claim.sub','11111111-1111-4111-8111-111111111111',true);
do $$declare t text;n bigint;begin foreach t in array array['customers','customer_contacts','projects','project_areas','organization_quotation_settings','quotations','quotation_revisions','quotation_items','quotation_item_costs'] loop execute format('select count(*) from public.%I where organization_id=$1',t) into n using current_setting('test.quote_other')::uuid;perform private.quote_assert(n=0,'cross-tenant RLS: '||t);perform private.quote_denied(format('delete from public.%I',t),array['42501'],'direct DML denied: '||t);end loop;end$$;
select private.quote_denied('select * from private.quotation_signing_keys',array['42501'],'signing key inaccessible');
select private.quote_denied('select private.quotation_catalog_data(''dddddddd-dddd-4ddd-8ddd-dddddddddddd'',null,null)',array['42501'],'private cost context inaccessible');
select private.quote_denied('select public.commit_quotation(''{}'',repeat(''0'',64))',array['42501'],'forged attestation rejected');
select private.quote_denied('select public.save_commercial_entity('''||:'other_org'||''',''customers'',''{"display_name":"stolen"}'')',array['42501'],'cross-tenant master RPC rejected');
select public.save_commercial_entity('dddddddd-dddd-4ddd-8ddd-dddddddddddd','customers','{"id":"b0000000-0000-4000-8000-000000000008","display_name":"Own customer"}');
select private.quote_denied('select public.save_commercial_entity(''dddddddd-dddd-4ddd-8ddd-dddddddddddd'',''customers'',''{"id":"b0000000-0000-4000-8000-000000000008","version":2,"display_name":"stale"}'')',array['40001'],'stale master version rejected');
select private.quote_denied('select public.save_commercial_entity(''dddddddd-dddd-4ddd-8ddd-dddddddddddd'',''projects'',''{"customer_id":"b0000000-0000-4000-8000-000000000002","name":"Bad","code":"bad"}'')',array['23503'],'cross-tenant project customer FK rejected');
select private.quote_assert((public.commercial_search('dddddddd-dddd-4ddd-8ddd-dddddddddddd','customers','Own',1)->>'total')::integer=1,'server prefix search');
select private.quote_assert((public.commercial_search('dddddddd-dddd-4ddd-8ddd-dddddddddddd','catalog_items','',1,'active',(select category_id from public.catalog_items where organization_id='dddddddd-dddd-4ddd-8ddd-dddddddddddd' and key='wardrobe'))->>'total')::integer=(select count(*) from public.catalog_items where organization_id='dddddddd-dddd-4ddd-8ddd-dddddddddddd' and status='active' and category_id=(select category_id from public.catalog_items where organization_id='dddddddd-dddd-4ddd-8ddd-dddddddddddd' and key='wardrobe')),'paginated active catalog category filtering');
reset role;
insert into public.projects(id,organization_id,customer_id,name,code) values('b0000000-0000-4000-8000-000000000009','dddddddd-dddd-4ddd-8ddd-dddddddddddd','b0000000-0000-4000-8000-000000000008','Own cost project','own-cost-test');
insert into public.quotations(id,organization_id,customer_id,project_id,quotation_number) values('b0000000-0000-4000-8000-000000000010','dddddddd-dddd-4ddd-8ddd-dddddddddddd','b0000000-0000-4000-8000-000000000008','b0000000-0000-4000-8000-000000000009','Q-OWN-COST');
insert into public.quotation_revisions(id,organization_id,quotation_id,project_id,revision_number,currency,valid_until,document_snapshot) values('b0000000-0000-4000-8000-000000000011','dddddddd-dddd-4ddd-8ddd-dddddddddddd','b0000000-0000-4000-8000-000000000010','b0000000-0000-4000-8000-000000000009',1,'INR',current_date,'{}');
insert into public.quotation_items(id,organization_id,revision_id,project_id,snapshot) values('b0000000-0000-4000-8000-000000000012','dddddddd-dddd-4ddd-8ddd-dddddddddddd','b0000000-0000-4000-8000-000000000011','b0000000-0000-4000-8000-000000000009','{"snapshot_version":1}');
insert into public.quotation_item_costs(organization_id,item_id,cost_snapshot) values('dddddddd-dddd-4ddd-8ddd-dddddddddddd','b0000000-0000-4000-8000-000000000012','{"estimatedCost":"999"}');
set local role authenticated;
select private.quote_assert((select count(*)=1 from public.quotation_item_costs where item_id='b0000000-0000-4000-8000-000000000012'),'Owner can read own internal cost');
select set_config('request.jwt.claim.sub','22222222-2222-4222-8222-222222222222',true);
select private.quote_assert(not private.has_permission('dddddddd-dddd-4ddd-8ddd-dddddddddddd','quotation.view_internal_cost'),'Sales lacks internal-cost permission');
select private.quote_assert(not private.has_permission('dddddddd-dddd-4ddd-8ddd-dddddddddddd','quotation.discount'),'Sales lacks discount permission');
select private.quote_assert(not private.has_permission('dddddddd-dddd-4ddd-8ddd-dddddddddddd','quotation.override_rate'),'Sales lacks override permission');
select private.quote_assert(not private.has_permission('dddddddd-dddd-4ddd-8ddd-dddddddddddd','quotation.issue'),'Sales lacks issue permission');
select private.quote_assert((select count(*)=0 from public.quotation_item_costs),'Sales receives no cost rows');
select private.quote_assert((select count(*)=1 from public.quotation_items where id='b0000000-0000-4000-8000-000000000012'),'Sales can read selling snapshot while cost stays protected');
reset role;
select private.quote_assert((select bool_and(relrowsecurity and relforcerowsecurity) from pg_class where oid in('public.customers'::regclass,'public.projects'::regclass,'public.quotation_revisions'::regclass,'public.quotation_items'::regclass,'public.quotation_item_costs'::regclass)),'commercial RLS enabled and forced');
select private.quote_assert((select count(*)=1 from public.customers where id=private.seed_uuid('business-os:demo:ravi')),'repeatable Ravi seed');
select private.quote_assert((select count(*)=1 from public.projects where id=private.seed_uuid('business-os:demo:3bhk')),'repeatable project seed');
select private.quote_assert((select count(*)=3 from public.project_areas where project_id=private.seed_uuid('business-os:demo:3bhk')),'repeatable three-area seed');
select private.quote_assert((select count(*)=1 from public.organization_quotation_settings where organization_id='dddddddd-dddd-4ddd-8ddd-dddddddddddd'),'repeatable quotation settings seed');
rollback;
